<?php $title = 'Solicitações de privacidade — gestão Felito'; $types = ['access' => 'Acesso', 'correction' => 'Correção', 'deletion' => 'Exclusão', 'portability' => 'Portabilidade']; ?>
<section class="content-layout manager-layout"><div class="manager-heading"><div><div class="eyebrow"><span class="dot"></span>Painel do gestor</div><h1>Privacidade</h1><p>Atenda solicitações dos titulares e registre o status do atendimento.</p></div><?php require BASE_PATH . '/views/admin_nav.php'; ?></div>
  <?php if (!$requests): ?><div class="panel empty-state"><h2>Nenhuma solicitação.</h2><p>Novos pedidos de atendimento aparecerão aqui.</p></div><?php else: ?><div class="admin-order-list"><?php foreach ($requests as $request): ?><article class="panel admin-order-card"><div class="admin-order-top"><div><span class="eyebrow"><?= e($types[$request['request_type']] ?? $request['request_type']) ?> · <?= e(localDateTime($request['created_at'])) ?></span><h2><?= e($request['name']) ?></h2><p class="contact-line"><a href="mailto:<?= e($request['email']) ?>"><?= e($request['email']) ?></a></p></div><span class="status status-<?= e($request['status']) ?>"><?= e($request['status']) ?></span></div><p><?= e($request['details'] ?? 'Sem detalhes adicionais.') ?></p><?php if ($request['status'] === 'open'): ?><div class="admin-actions"><form method="post"><?= csrfField() ?><input type="hidden" name="request_id" value="<?= (int) $request['id'] ?>"><input type="hidden" name="status" value="completed"><button class="button button-primary button-small" type="submit">Marcar atendida</button></form><form method="post"><?= csrfField() ?><input type="hidden" name="request_id" value="<?= (int) $request['id'] ?>"><input type="hidden" name="status" value="rejected"><button class="button button-outline button-small" type="submit">Marcar não atendida</button></form></div><?php endif ?></article><?php endforeach ?></div><?php endif ?>
</section>
